define([],function(){'use strict';function uuid(){var cryptoApi=typeof window!=='undefined'&&window.crypto?window.crypto:null;if(cryptoApi&&cryptoApi.randomUUID){return cryptoApi.randomUUID().replace(/-/g,'');}if(cryptoApi&&cryptoApi.getRandomValues){var bytes=new Uint8Array(16);cryptoApi.getRandomValues(bytes);return Array.prototype.map.call(bytes,function(byte){return('0'+byte.toString(16)).slice(-2);}).join('');}uuid.counter=(uuid.counter||0)+1;var perfApi=typeof window!=='undefined'&&window.performance?window.performance:null;var perf=perfApi&&typeof perfApi.now==='function'?Math.floor(perfApi.now()*1000).toString(36):'0';var identifier=Date.now().toString(36)+perf+uuid.counter.toString(36);while(identifier.length<16){identifier+=Date.now().toString(36)+uuid.counter.toString(36);}return('sess'+identifier).substring(0,52);}return{uuid:uuid};});
